package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

class PreferencesRepository(context: Context) {
    private val prefs = context.getSharedPreferences("zapptv", Context.MODE_PRIVATE)

    fun lastChannelId(): String? = prefs.getString(KEY_LAST_CHANNEL, null)

    fun setLastChannel(id: String) {
        prefs.edit().putString(KEY_LAST_CHANNEL, id).apply()
    }

    fun favorites(): Set<String> =
        prefs.getStringSet(KEY_FAVORITES, emptySet()).orEmpty().toSet()

    fun captionsEnabled(): Boolean = prefs.getBoolean(KEY_CAPTIONS_ENABLED, false)

    fun startInLastChannel(): Boolean = prefs.getBoolean(KEY_START_LAST_CHANNEL, false)

    fun preferredAudioLanguage(): String? =
        prefs.getString(KEY_AUDIO_LANGUAGE, "pt-BR")?.takeIf { it.isNotBlank() }

    fun setPreferredAudioLanguage(language: String?) {
        prefs.edit().putString(KEY_AUDIO_LANGUAGE, language.orEmpty()).apply()
    }

    fun maxVideoHeight(): Int = prefs.getInt(KEY_MAX_VIDEO_HEIGHT, 0)

    fun setMaxVideoHeight(height: Int) {
        prefs.edit().putInt(KEY_MAX_VIDEO_HEIGHT, height.coerceAtLeast(0)).apply()
    }

    fun setStartInLastChannel(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_START_LAST_CHANNEL, enabled).apply()
    }

    fun setCaptionsEnabled(enabled: Boolean) {
        prefs.edit().putBoolean(KEY_CAPTIONS_ENABLED, enabled).apply()
    }

    fun setFavorite(id: String, favorite: Boolean) {
        val updated = favorites().toMutableSet()
        if (favorite) updated += id else updated -= id
        prefs.edit().putStringSet(KEY_FAVORITES, updated).apply()
    }

    fun recentChannelIds(limit: Int = 40): List<String> {
        val raw = prefs.getString(KEY_RECENT, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    val id = array.optString(index)
                    if (id.isNotBlank()) add(id)
                    if (size >= limit) break
                }
            }
        }.getOrDefault(emptyList())
    }

    fun watchCounts(): Map<String, Int> {
        val raw = prefs.getString(KEY_WATCH_COUNTS, null) ?: return emptyMap()
        return runCatching {
            val json = JSONObject(raw)
            buildMap {
                json.keys().forEach { key ->
                    val count = json.optInt(key, 0)
                    if (count > 0) put(key, count)
                }
            }
        }.getOrDefault(emptyMap())
    }

    fun recordTune(id: String) {
        val recent = recentChannelIds(limit = MAX_RECENTS)
            .filterNot { it == id }
            .toMutableList()
            .apply { add(0, id) }
            .take(MAX_RECENTS)

        val recentJson = JSONArray()
        recent.forEach(recentJson::put)

        val counts = watchCounts().toMutableMap()
        counts[id] = (counts[id] ?: 0).coerceAtMost(MAX_WATCH_COUNT - 1) + 1

        val countsJson = JSONObject()
        counts.forEach { (channelId, count) -> countsJson.put(channelId, count) }

        prefs.edit()
            .putString(KEY_RECENT, recentJson.toString())
            .putString(KEY_WATCH_COUNTS, countsJson.toString())
            .apply()
    }

    companion object {
        private const val KEY_LAST_CHANNEL = "last_channel"
        private const val KEY_FAVORITES = "favorites"
        private const val KEY_CAPTIONS_ENABLED = "captions_enabled"
        private const val KEY_START_LAST_CHANNEL = "start_last_channel"
        private const val KEY_AUDIO_LANGUAGE = "preferred_audio_language"
        private const val KEY_MAX_VIDEO_HEIGHT = "max_video_height"
        private const val KEY_RECENT = "recent_channels_v2"
        private const val KEY_WATCH_COUNTS = "watch_counts_v2"
        private const val MAX_RECENTS = 80
        private const val MAX_WATCH_COUNT = 1_000_000
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONObject

data class SourceHealth(
    val sourceId: String,
    val lastAttemptMillis: Long = 0L,
    val lastSuccessMillis: Long = 0L,
    val successCount: Int = 0,
    val failureCount: Int = 0,
    val channelCount: Int = 0
) {
    val isHealthy: Boolean
        get() = lastSuccessMillis > 0L && (
            lastAttemptMillis == 0L || lastSuccessMillis >= lastAttemptMillis
        )

    fun reliabilityScore(): Int {
        val total = successCount + failureCount
        if (total <= 0) return 0
        return ((successCount.toFloat() / total.toFloat()) * 100f).toInt()
    }
}

class SourceHealthStore(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv-source-health", Context.MODE_PRIVATE)

    fun get(sourceId: String): SourceHealth {
        val raw = prefs.getString(sourceId, null) ?: return SourceHealth(sourceId)
        return runCatching {
            val json = JSONObject(raw)
            SourceHealth(
                sourceId = sourceId,
                lastAttemptMillis = json.optLong("lastAttemptMillis", 0L),
                lastSuccessMillis = json.optLong("lastSuccessMillis", 0L),
                successCount = json.optInt("successCount", 0),
                failureCount = json.optInt("failureCount", 0),
                channelCount = json.optInt("channelCount", 0)
            )
        }.getOrDefault(SourceHealth(sourceId))
    }

    fun recordSuccess(sourceId: String, channelCount: Int) {
        val old = get(sourceId)
        save(
            old.copy(
                lastAttemptMillis = System.currentTimeMillis(),
                lastSuccessMillis = System.currentTimeMillis(),
                successCount = (old.successCount + 1).coerceAtMost(MAX_COUNT),
                channelCount = channelCount.coerceAtLeast(0)
            )
        )
    }

    fun recordFailure(sourceId: String) {
        val old = get(sourceId)
        save(
            old.copy(
                lastAttemptMillis = System.currentTimeMillis(),
                failureCount = (old.failureCount + 1).coerceAtMost(MAX_COUNT)
            )
        )
    }

    fun snapshot(sourceIds: List<String>): Map<String, SourceHealth> =
        sourceIds.associateWith(::get)

    private fun save(health: SourceHealth) {
        val json = JSONObject()
            .put("lastAttemptMillis", health.lastAttemptMillis)
            .put("lastSuccessMillis", health.lastSuccessMillis)
            .put("successCount", health.successCount)
            .put("failureCount", health.failureCount)
            .put("channelCount", health.channelCount)

        prefs.edit().putString(health.sourceId, json.toString()).apply()
    }

    companion object {
        private const val MAX_COUNT = 1_000_000
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import com.mukasanches.zapptv.BuildConfig
import okhttp3.OkHttpClient
import okhttp3.Request
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import java.security.MessageDigest
import java.util.concurrent.TimeUnit

data class UpdateCheck(
    val available: Boolean = false,
    val latestVersion: String? = null,
    val apkUrl: String? = null,
    val sha256: String? = null,
    val notes: String? = null,
    val status: String = "Atualização não verificada"
)

class UpdateRepository(context: Context) {
    private val appContext = context.applicationContext

    private val client = OkHttpClient.Builder()
        .connectTimeout(5, TimeUnit.SECONDS)
        .readTimeout(20, TimeUnit.SECONDS)
        .callTimeout(90, TimeUnit.SECONDS)
        .retryOnConnectionFailure(true)
        .build()

    fun check(): UpdateCheck {
        val request = Request.Builder()
            .url(RELEASE_MANIFEST_URL)
            .header("User-Agent", "SANCHESTV/${BuildConfig.VERSION_NAME}")
            .header("Cache-Control", "no-cache")
            .build()

        return runCatching {
            client.newCall(request).execute().use { response ->
                if (!response.isSuccessful) {
                    return@use UpdateCheck(status = "Servidor de atualização indisponível")
                }

                val body = response.body.string()
                val json = JSONObject(body)
                val versionCode = json.optInt("versionCode", 0)
                val versionName = json.optString("versionName").takeIf(String::isNotBlank)
                val apkUrl = json.optString("apkUrl").takeIf { it.startsWith("https://") }
                val sha256 = json.optString("sha256")
                    .trim()
                    .lowercase()
                    .takeIf { it.matches(Regex("[0-9a-f]{64}")) }
                val notes = json.optString("notes").takeIf(String::isNotBlank)

                val available =
                    versionCode > BuildConfig.VERSION_CODE &&
                        apkUrl != null &&
                        sha256 != null

                UpdateCheck(
                    available = available,
                    latestVersion = versionName,
                    apkUrl = apkUrl,
                    sha256 = sha256,
                    notes = notes,
                    status = if (available) {
                        "SANCHESTV ${versionName ?: versionCode} disponível"
                    } else {
                        "Você está na versão mais recente"
                    }
                )
            }
        }.getOrElse {
            UpdateCheck(status = "Não foi possível verificar atualizações")
        }
    }

    fun downloadVerified(apkUrl: String, expectedSha256: String): File? {
        if (!apkUrl.startsWith("https://", ignoreCase = true)) return null
        val expected = expectedSha256.trim().lowercase()
        if (!expected.matches(Regex("[0-9a-f]{64}"))) return null

        val directory = File(appContext.cacheDir, "updates").apply { mkdirs() }
        val temp = File(directory, "sanchestv-update.apk.part")
        val output = File(directory, "sanchestv-update.apk")
        val digest = MessageDigest.getInstance("SHA-256")

        val request = Request.Builder()
            .url(apkUrl)
            .header("User-Agent", "SANCHESTV/${BuildConfig.VERSION_NAME}")
            .build()

        return runCatching {
            client.newCall(request).execute().use { response ->
                require(response.isSuccessful) { "HTTP ${response.code}" }
                val declaredLength = response.body.contentLength()
                require(declaredLength <= MAX_APK_BYTES || declaredLength < 0L) {
                    "APK excede limite seguro"
                }

                FileOutputStream(temp).use { sink ->
                    response.body.byteStream().use { source ->
                        val buffer = ByteArray(DEFAULT_BUFFER_SIZE)
                        var total = 0L
                        while (true) {
                            val count = source.read(buffer)
                            if (count <= 0) break
                            total += count
                            require(total <= MAX_APK_BYTES) { "APK excede limite seguro" }
                            digest.update(buffer, 0, count)
                            sink.write(buffer, 0, count)
                        }
                        sink.fd.sync()
                    }
                }

                val actual = digest.digest().joinToString("") { "%02x".format(it) }
                require(actual == expected) { "SHA-256 inválido" }
                require(temp.length() > 0L) { "APK vazio" }

                if (!temp.renameTo(output)) {
                    temp.copyTo(output, overwrite = true)
                    temp.delete()
                }
                output
            }
        }.getOrElse {
            temp.delete()
            null
        }
    }

    companion object {
        const val RELEASE_MANIFEST_URL =
            "https://sanchestv-release.onrender.com/release-manifest.json"
        private const val MAX_APK_BYTES = 300L * 1024L * 1024L
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONArray
import java.net.URI
import java.security.MessageDigest

class UserM3uSourceStore(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv-user-sources", Context.MODE_PRIVATE)

    fun sources(): List<IptvSource> {
        val raw = prefs.getString(KEY_SOURCES, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    val url = array.optString(index).trim()
                    toSource(url)?.let(::add)
                }
            }.distinctBy { it.id }
        }.getOrDefault(emptyList())
    }

    fun add(url: String): IptvSource? {
        val source = toSource(url) ?: return null
        val updated = (sources().map(IptvSource::url) + source.url)
            .distinct()
            .take(MAX_USER_SOURCES)

        val array = JSONArray()
        updated.forEach(array::put)
        prefs.edit().putString(KEY_SOURCES, array.toString()).apply()
        return source
    }

    fun remove(id: String) {
        val updated = sources().filterNot { it.id == id }.map(IptvSource::url)
        val array = JSONArray()
        updated.forEach(array::put)
        prefs.edit().putString(KEY_SOURCES, array.toString()).apply()
    }

    private fun toSource(rawUrl: String): IptvSource? {
        val url = rawUrl.trim()
        if (!url.startsWith("https://", ignoreCase = true)) return null

        val uri = runCatching { URI(url) }.getOrNull() ?: return null
        val host = uri.host?.takeIf(String::isNotBlank) ?: return null
        val id = "user-" + shortHash(url)

        return IptvSource(
            id = id,
            name = "Minha fonte • $host",
            url = url,
            priority = 130,
            market = "Adicionada pelo usuário",
            enabled = true
        )
    }

    private fun shortHash(value: String): String {
        val digest = MessageDigest.getInstance("SHA-256").digest(value.toByteArray())
        return digest.take(8).joinToString("") { "%02x".format(it) }
    }

    companion object {
        private const val KEY_SOURCES = "https_m3u_sources"
        private const val MAX_USER_SOURCES = 24
    }
}

package com.mukasanches.zapptv.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

data class UserPlaylist(
    val id: String,
    val name: String,
    val url: String,
    val enabled: Boolean = true
)

class UserPlaylistStore(context: Context) {
    private val prefs = context.getSharedPreferences("sanchestv_user_playlists", Context.MODE_PRIVATE)

    fun playlists(): List<UserPlaylist> {
        val raw = prefs.getString(KEY_PLAYLISTS, null) ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (index in 0 until array.length()) {
                    val item = array.optJSONObject(index) ?: continue
                    val id = item.optString("id").trim()
                    val name = item.optString("name").trim()
                    val url = item.optString("url").trim()
                    if (id.isBlank() || name.isBlank() || !isSafeUrl(url)) continue
                    add(
                        UserPlaylist(
                            id = id,
                            name = name,
                            url = url,
                            enabled = item.optBoolean("enabled", true)
                        )
                    )
                }
            }
        }.getOrDefault(emptyList())
    }

    fun add(name: String, url: String): Boolean {
        val cleanUrl = url.trim()
        if (!isSafeUrl(cleanUrl)) return false

        val cleanName = name.trim().replace(Regex("\\s+"), " ").take(60)
            .ifBlank { "Minha playlist" }

        val id = "user-" + cleanUrl.hashCode().toUInt().toString(16)
        val current = playlists().filterNot { it.id == id }.toMutableList()
        current += UserPlaylist(id = id, name = cleanName, url = cleanUrl)
        save(current)
        return true
    }

    fun remove(id: String) {
        save(playlists().filterNot { it.id == id })
    }

    fun setEnabled(id: String, enabled: Boolean) {
        save(
            playlists().map {
                if (it.id == id) it.copy(enabled = enabled) else it
            }
        )
    }

    fun sources(): List<IptvSource> =
        playlists()
            .filter { it.enabled }
            .mapIndexed { index, playlist ->
                IptvSource(
                    id = playlist.id,
                    name = playlist.name,
                    url = playlist.url,
                    priority = 150 - index.coerceAtMost(40),
                    market = "Playlist do usuário",
                    enabled = true
                )
            }

    private fun save(items: List<UserPlaylist>) {
        val array = JSONArray()
        items.take(MAX_PLAYLISTS).forEach { playlist ->
            array.put(
                JSONObject()
                    .put("id", playlist.id)
                    .put("name", playlist.name)
                    .put("url", playlist.url)
                    .put("enabled", playlist.enabled)
            )
        }
        prefs.edit().putString(KEY_PLAYLISTS, array.toString()).apply()
    }

    private fun isSafeUrl(value: String): Boolean =
        value.startsWith("https://", ignoreCase = true)

    companion object {
        private const val KEY_PLAYLISTS = "playlists"
        private const val MAX_PLAYLISTS = 20
    }
}

package com.mukasanches.zapptv.data

import com.mukasanches.zapptv.model.Channel
import com.mukasanches.zapptv.model.ProgramInfo
import com.mukasanches.zapptv.model.ProgramSlot
import org.xml.sax.Attributes
import org.xml.sax.helpers.DefaultHandler
import java.io.File
import java.text.SimpleDateFormat
import java.util.Locale
import javax.xml.parsers.SAXParserFactory

data class EpgSchedule(
    val currentPrograms: Map<String, ProgramInfo> = emptyMap(),
    val timeline: Map<String, List<ProgramSlot>> = emptyMap()
)

object XmlTvParser {
    fun parseCurrentPrograms(
        file: File,
        channels: List<Channel>,
        now: Long = System.currentTimeMillis()
    ): Map<String, ProgramInfo> =
        parseSchedule(file, channels, now).currentPrograms

    fun parseSchedule(
        file: File,
        channels: List<Channel>,
        now: Long = System.currentTimeMillis(),
        horizonMillis: Long = DEFAULT_HORIZON_MS
    ): EpgSchedule {
        if (!file.isFile || file.length() == 0L) return EpgSchedule()

        val channelIdsByEpg = channels
            .mapNotNull { channel -> channel.epgId?.let { it to channel.id } }
            .groupBy({ it.first }, { it.second })
        if (channelIdsByEpg.isEmpty()) return EpgSchedule()

        val slots = linkedMapOf<String, MutableList<ProgramSlot>>()
        val factory = SAXParserFactory.newInstance().apply {
            isNamespaceAware = false
            isValidating = false
            runCatching { setFeature("http://xml.org/sax/features/external-general-entities", false) }
            runCatching { setFeature("http://xml.org/sax/features/external-parameter-entities", false) }
            runCatching { setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false) }
        }

        runCatching {
            factory.newSAXParser().parse(
                file,
                ScheduleHandler(
                    channelIdsByEpg = channelIdsByEpg,
                    now = now,
                    horizonMillis = horizonMillis,
                    slots = slots
                )
            )
        }

        val timeline = slots.mapValues { (_, value) ->
            value
                .distinctBy { "${it.startMillis}:${it.endMillis}:${it.title}" }
                .sortedBy(ProgramSlot::startMillis)
                .take(MAX_PROGRAMS_PER_CHANNEL)
        }

        val currentPrograms = linkedMapOf<String, ProgramInfo>()
        timeline.forEach { (channelId, programs) ->
            val current = programs.lastOrNull { it.isLive(now) }
            if (current != null) {
                val next = programs.firstOrNull { it.startMillis >= current.endMillis }
                    ?: programs.firstOrNull { it.startMillis > now }
                currentPrograms[channelId] = ProgramInfo(
                    channelId = channelId,
                    title = current.title,
                    subtitle = current.subtitle,
                    description = current.description,
                    startMillis = current.startMillis,
                    endMillis = current.endMillis,
                    nextTitle = next?.title,
                    nextStartMillis = next?.startMillis,
                    nextEndMillis = next?.endMillis
                )
            }
        }

        return EpgSchedule(
            currentPrograms = currentPrograms,
            timeline = timeline
        )
    }

    private class ScheduleHandler(
        private val channelIdsByEpg: Map<String, List<String>>,
        private val now: Long,
        private val horizonMillis: Long,
        private val slots: MutableMap<String, MutableList<ProgramSlot>>
    ) : DefaultHandler() {
        private var active = false
        private var activeEpgId: String? = null
        private var startMillis: Long? = null
        private var endMillis: Long? = null
        private var currentField: String? = null
        private val text = StringBuilder()
        private var title: String? = null
        private var subtitle: String? = null
        private var description: String? = null

        override fun startElement(
            uri: String?,
            localName: String?,
            qName: String,
            attributes: Attributes
        ) {
            when (qName.lowercase(Locale.ROOT)) {
                "programme" -> {
                    resetProgram()
                    val epgId = attributes.getValue("channel") ?: return
                    if (epgId !in channelIdsByEpg) return

                    val start = parseXmlTvTime(attributes.getValue("start")) ?: return
                    val stop = parseXmlTvTime(attributes.getValue("stop")) ?: (start + SIX_HOURS_MS)
                    if (stop <= now) return
                    if (start > now + horizonMillis) return

                    active = true
                    activeEpgId = epgId
                    startMillis = start
                    endMillis = stop
                }

                "title", "sub-title", "desc" -> if (active) {
                    currentField = qName.lowercase(Locale.ROOT)
                    text.setLength(0)
                }
            }
        }

        override fun characters(ch: CharArray, start: Int, length: Int) {
            if (active && currentField != null) text.append(ch, start, length)
        }

        override fun endElement(uri: String?, localName: String?, qName: String) {
            val element = qName.lowercase(Locale.ROOT)
            if (active && currentField == element) {
                val value = text.toString().trim().takeIf(String::isNotBlank)
                when (element) {
                    "title" -> if (title == null) title = value
                    "sub-title" -> if (subtitle == null) subtitle = value
                    "desc" -> if (description == null) description = value
                }
                currentField = null
                text.setLength(0)
            }

            if (element == "programme" && active) {
                val epgId = activeEpgId
                val start = startMillis
                val end = endMillis
                if (epgId != null && start != null && end != null) {
                    channelIdsByEpg[epgId].orEmpty().forEach { channelId ->
                        slots.getOrPut(channelId) { mutableListOf() }.add(
                            ProgramSlot(
                                channelId = channelId,
                                title = title ?: "Ao vivo",
                                subtitle = subtitle,
                                description = description,
                                startMillis = start,
                                endMillis = end
                            )
                        )
                    }
                }
                resetProgram()
            }
        }

        private fun resetProgram() {
            active = false
            activeEpgId = null
            startMillis = null
            endMillis = null
            currentField = null
            text.setLength(0)
            title = null
            subtitle = null
            description = null
        }
    }

    private fun parseXmlTvTime(value: String?): Long? {
        val raw = value?.trim().orEmpty()
        if (raw.isBlank()) return null

        val patterns = listOf(
            "yyyyMMddHHmmss Z",
            "yyyyMMddHHmm Z",
            "yyyyMMddHHmmss",
            "yyyyMMddHHmm"
        )

        for (pattern in patterns) {
            val parsed = runCatching {
                SimpleDateFormat(pattern, Locale.US).apply {
                    isLenient = false
                }.parse(raw)?.time
            }.getOrNull()
            if (parsed != null) return parsed
        }
        return null
    }

    private const val SIX_HOURS_MS = 6L * 60L * 60L * 1000L
    private const val DEFAULT_HORIZON_MS = 7L * 24L * 60L * 60L * 1000L
    private const val MAX_PROGRAMS_PER_CHANNEL = 336
}
